"use client"

import { usePart, usePrimitive } from "@ui-sdk/react/primitive"
import { PauseIcon, PlayIcon } from "lucide-react"
import { useRef, useState, useSyncExternalStore } from "react"

import type { LedColor, LedMatrixMode } from "@/components/ui/led-matrix-engine"
import { ledMatrix, type LedMatrixOptions } from "@/components/ui/led-matrix-primitive"
import { Toggle } from "@/components/ui/toggle"
import { useLedMatrixScene } from "@/components/ui/use-led-matrix-scene"
import { cn, cssVars, type StateClassName } from "@/lib/utils"

type LedMatrixLabels = {
  /** Names the pause toggle, for screen readers, agents and its tooltip. */
  pause: string
}

const ledMatrixLabels: LedMatrixLabels = { pause: "Pause" }

type LedMatrixState = { paused: boolean; color: LedColor }

type LedMatrixProps = LedMatrixOptions & {
  /** The sign's accessible name: "Next departures", "Pharmacy". */
  label: string
  /** The colour of the lit dots. Default `amber`. */
  color?: LedColor
  /** `scroll` (the default) runs each message right to left; `hold` shows it still, a page at a time. */
  mode?: LedMatrixMode
  /** Scroll speed in dots per second. Default 24. */
  speed?: number
  /** How long a held message or page stays, in ms. Default 3000. */
  holdMs?: number
  /** Dots across. Default 96. */
  columns?: number
  /** Dots down. Default 9; 14 or more doubles the 5×7 glyphs. */
  rows?: number
  /** Shows the pause toggle, which motion that starts by itself needs. Default true. */
  controls?: boolean
  labels?: Partial<LedMatrixLabels>
  /** Classes for the housing; a function gets the sign's state. */
  className?: StateClassName<LedMatrixState>
  /** Called with each canvas paint's duration in ms, for measuring. */
  onPaint?: (milliseconds: number) => void
}

const dataAttributes = (values: Record<string, string | undefined>): Record<`data-${string}`, string | undefined> =>
  Object.fromEntries(Object.entries(values).map(([key, value]) => [`data-${key}`, value]))

/**
 * A bus or pharmacy dot-matrix sign: a board of round LEDs behind smoked glass, with messages that scroll or hold in
 * turn, drawn from its own 5×7 font (Latin-1 and €). It paints a canvas only when a dot changes, and only on screen;
 * under reduced motion a scrolling sign shows its messages a page at a time.
 */
function LedMatrix({
  label,
  messages,
  defaultMessages,
  onMessagesChange,
  paused,
  defaultPaused,
  onPausedChange,
  live,
  color = "amber",
  mode = "scroll",
  speed = 24,
  holdMs = 3000,
  columns = 96,
  rows = 9,
  controls = true,
  labels: ownLabels,
  className,
  onPaint,
}: LedMatrixProps) {
  const labels = { ...ledMatrixLabels, ...ownLabels }
  const handle = usePrimitive(ledMatrix, {
    messages,
    defaultMessages,
    onMessagesChange,
    paused,
    defaultPaused,
    onPausedChange,
    live,
  })
  useSyncExternalStore(handle.instance.subscribe, handle.instance.get, handle.instance.get)
  const board = useRef<HTMLDivElement>(null)
  const canvas = useRef<HTMLCanvasElement>(null)
  const [elements] = useState(() => ({ board, canvas }))
  const state = handle.state
  const message = useLedMatrixScene(
    elements,
    { messages: state.messages, columns, rows, mode, speed, holdMs, color, paused: state.paused },
    onPaint,
  )

  const children = (
    <>
      <div ref={board} data-slot="led-matrix-board" style={cssVars({ "--led-columns": columns, "--led-rows": rows })}>
        <canvas ref={canvas} data-slot="led-matrix-dots" aria-hidden="true" />
      </div>
      <p data-slot="led-matrix-text" className="sr-only">
        {state.messages[message] ?? ""}
      </p>
      {controls ? (
        <Toggle
          size="icon"
          aria-label={labels.pause}
          pressed={state.paused}
          onPressedChange={(next, details) =>
            next
              ? handle.api.pause({ reason: "trigger-press", event: details.event })
              : handle.api.resume({ reason: "trigger-press", event: details.event })
          }
          data-led-matrix-pause=""
        >
          {state.paused ? <PlayIcon /> : <PauseIcon />}
        </Toggle>
      ) : null}
    </>
  )

  return usePart(
    handle,
    "root",
    {},
    {
      "aria-label": label,
      ...dataAttributes({ color, mode }),
      children,
      className: cn(
        "relative flex w-full items-center gap-items",
        typeof className === "function" ? className({ paused: state.paused, color }) : className,
      ),
    },
    "div",
  )
}

export { LedMatrix, ledMatrixLabels }
export type { LedColor, LedMatrixLabels, LedMatrixMode, LedMatrixProps, LedMatrixState }

import { createChange, definePrimitive, type ChangeDetails } from "@ui-sdk/core"

import { settled, unavailable } from "@/lib/action-refusal"
import { isStringArray } from "@/lib/narrow"

/** Why the messages or the pause changed: the pause toggle (`trigger-press`), or an agent or your code (`imperative`). */
type LedMatrixChangeReason = "trigger-press" | "imperative"

type LedMatrixOptions = {
  messages?: readonly string[]
  defaultMessages?: readonly string[]
  /** Asks to show other messages; `details.cancel()` keeps the ones shown. */
  onMessagesChange?: (messages: string[], details: ChangeDetails<LedMatrixChangeReason>) => void
  paused?: boolean
  defaultPaused?: boolean
  /** Asks to stop or go on: the pause toggle, an agent's `pause` and `resume`. `details.cancel()` refuses it. */
  onPausedChange?: (paused: boolean, details: ChangeDetails<LedMatrixChangeReason>) => void
  /** `polite` reads each new message to screen readers as it comes up; `off` (the default) leaves it to be found. */
  live?: "off" | "polite"
}

type Call = { reason?: LedMatrixChangeReason; event?: Event | undefined }

function messagesOf(value: unknown): string[] | undefined {
  const list = typeof value === "string" ? [value] : value
  if (!isStringArray(list)) return undefined
  const messages = list.map((message) => message.trim()).filter(Boolean)
  return messages.length ? messages : undefined
}

const sameMessages = (a: readonly string[], b: readonly string[]) =>
  a.length === b.length && a.every((message, index) => message === b[index])

const ledMatrix = definePrimitive({
  name: "led-matrix",
  options: {
    messages: "list",
    defaultMessages: "list",
    onMessagesChange: "callback",
    paused: "boolean",
    defaultPaused: "boolean",
    onPausedChange: "callback",
    live: "string",
  },
  controlled: ["messages", "paused"],
  state: (options: LedMatrixOptions) => ({
    messages: [...(options.messages ?? options.defaultMessages ?? [])],
    paused: options.paused ?? options.defaultPaused ?? false,
    live: options.live ?? "off",
  }),
  sync: (options) => ({
    ...(options.messages === undefined ? {} : { messages: [...options.messages] }),
    ...(options.paused === undefined ? {} : { paused: options.paused }),
    live: options.live ?? "off",
  }),
  api: (context) => {
    const change = createChange(context)
    const setPaused = (paused: boolean, action: string, { reason = "imperative", event }: Call = {}) => {
      if (context.store.get().paused === paused) return true
      return settled(change("paused", paused, { reason, event }), action, { reason, event })
    }
    return {
      /** Shows these messages from the first, in turn; a single string is one message. */
      setMessages(messages: unknown, event?: Event) {
        const next = messagesOf(messages)
        if (!next) return unavailable("setMessages", "takes a list of messages with text", { event })
        if (sameMessages(next, context.store.get().messages)) return true
        return settled(change("messages", next, { reason: "imperative", event }), "setMessages", { event })
      },
      /** Stops the sign where it is. */
      pause: (call?: Call) => setPaused(true, "pause", call),
      /** Goes on from where the sign stopped. */
      resume: (call?: Call) => setPaused(false, "resume", call),
    }
  },
  slots: (slot) => ({
    root: slot({
      role: "marquee",
      attrs: (state) => ({
        "aria-live": state.live,
        "data-paused": state.paused ? "" : undefined,
      }),
    }),
  }),
  agent: { actions: ["setMessages", "pause", "resume"] },
})

export { ledMatrix }
export type { LedMatrixChangeReason, LedMatrixOptions }

import { glyphRows, pagesOf, textColumns } from "@/components/ui/led-matrix-font"

type LedColor = "amber" | "red" | "green" | "white"

/** How a message moves: `scroll` runs it right to left; `hold` shows it still, a page at a time when it's too long. */
type LedMatrixMode = "scroll" | "hold"

type LedPalette = { core: string; lit: string; glow: string; unlit: string; rim: string }

const ledPalettes: Record<LedColor, LedPalette> = {
  amber: { core: "#fff4d6", lit: "#ffb020", glow: "#ff8800", unlit: "#2a1b08", rim: "#4a3418" },
  red: { core: "#ffe0d8", lit: "#ff4128", glow: "#ff1800", unlit: "#2a0c08", rim: "#4a1e18" },
  green: { core: "#eaffee", lit: "#52ff74", glow: "#00e046", unlit: "#0a2210", rim: "#1c3e24" },
  white: { core: "#ffffff", lit: "#eef3ff", glow: "#b8ccff", unlit: "#1c1e24", rim: "#383c46" },
}

const boardColor = "#070605"

type LedMatrixSettings = {
  messages: readonly string[]
  columns: number
  rows: number
  mode: LedMatrixMode
  /** Scroll speed in dots per second. */
  speed: number
  /** How long a held message or page stays, in ms. */
  holdMs: number
  color: LedColor
  paused: boolean
}

type LedMatrixHandlers = {
  /** Called with the index of the message that comes up. */
  onMessage: (index: number) => void
  /** Called with each paint's duration in ms. */
  onPaint?: ((milliseconds: number) => void) | undefined
}

type Frame = { columns: number[]; offset: number }

const softwareRenderer = /swiftshader|llvmpipe|softpipe|basic render|warp/i
type CanvasPlan = { settings: CanvasRenderingContext2DSettings; maxRatio: number }
let canvasPlan: CanvasPlan | undefined

function rendererName(gl: WebGLRenderingContext) {
  const generic = String(gl.getParameter(gl.RENDERER))
  const debug = generic === "WebKit WebGL" ? gl.getExtension("WEBGL_debug_renderer_info") : null
  return debug ? String(gl.getParameter(debug.UNMASKED_RENDERER_WEBGL)) : generic
}

function planCanvas(): CanvasPlan {
  if (canvasPlan) return canvasPlan
  const gl = document.createElement("canvas").getContext("webgl")
  const software = gl ? softwareRenderer.test(rendererName(gl)) : true
  gl?.getExtension("WEBGL_lose_context")?.loseContext()
  canvasPlan = { settings: { willReadFrequently: software }, maxRatio: software ? 1 : 2 }
  return canvasPlan
}

const prefersReducedMotion = () =>
  typeof matchMedia === "function" && matchMedia("(prefers-reduced-motion: reduce)").matches

function sized(canvas: HTMLCanvasElement, width: number, height: number) {
  if (canvas.width !== width) canvas.width = width
  if (canvas.height !== height) canvas.height = height
  return canvas.getContext("2d", planCanvas().settings)
}

type Geometry = { pitch: number; left: number; top: number; ratio: number }

function geometryOf(width: number, height: number, settings: LedMatrixSettings): Geometry {
  const ratio = Math.min(planCanvas().maxRatio, devicePixelRatio || 1)
  const pitch = Math.min(width / settings.columns, height / settings.rows) * ratio
  return {
    pitch,
    left: (width * ratio - pitch * settings.columns) / 2,
    top: (height * ratio - pitch * settings.rows) / 2,
    ratio,
  }
}

function litSprite(pitch: number, palette: LedPalette) {
  const sprite = document.createElement("canvas")
  const size = Math.max(4, Math.ceil(pitch * 2.4))
  const context = sized(sprite, size, size)
  if (!context) return sprite
  const centre = size / 2
  const glow = context.createRadialGradient(centre, centre, 0, centre, centre, centre)
  glow.addColorStop(0, palette.core)
  glow.addColorStop(0.1, palette.lit)
  glow.addColorStop(0.2, palette.lit)
  glow.addColorStop(0.24, `${palette.glow}88`)
  glow.addColorStop(0.45, `${palette.glow}22`)
  glow.addColorStop(1, `${palette.glow}00`)
  context.fillStyle = glow
  context.fillRect(0, 0, size, size)
  return sprite
}

function paintUnlit(
  canvas: HTMLCanvasElement,
  width: number,
  height: number,
  geometry: Geometry,
  settings: LedMatrixSettings,
) {
  const context = sized(canvas, width, height)
  if (!context) return
  const palette = ledPalettes[settings.color]
  const { pitch, left, top } = geometry
  const radius = pitch * 0.34
  context.fillStyle = boardColor
  context.fillRect(0, 0, width, height)
  for (let row = 0; row < settings.rows; row++) {
    for (let column = 0; column < settings.columns; column++) {
      const x = left + (column + 0.5) * pitch
      const y = top + (row + 0.5) * pitch
      const lens = context.createRadialGradient(x - radius * 0.3, y - radius * 0.35, 0, x, y, radius)
      lens.addColorStop(0, palette.rim)
      lens.addColorStop(0.7, palette.unlit)
      lens.addColorStop(1, "#000000")
      context.fillStyle = lens
      context.beginPath()
      context.arc(x, y, radius, 0, Math.PI * 2)
      context.fill()
    }
  }
}

/**
 * Drives a dot-matrix sign on a canvas: it steps a message across a dot at a time, or holds it a page at a time, and
 * paints only when a dot changes, only while the board is on screen and the page is visible.
 */
function createLedMatrixEngine(canvas: HTMLCanvasElement, board: HTMLElement, handlers: LedMatrixHandlers) {
  let settings: LedMatrixSettings | undefined
  let size = { width: 0, height: 0 }
  let unlit: HTMLCanvasElement | undefined
  let sprite: HTMLCanvasElement | undefined
  let geometry: Geometry | undefined
  let onScreen = true
  let reduced = prefersReducedMotion()
  let message = 0
  let page = 0
  let offset = 0
  let shown: Frame = { columns: [], offset: 0 }
  let frame = 0
  let timer: ReturnType<typeof setTimeout> | undefined
  let started = 0
  let startOffset = 0
  const columnsCache = new Map<string, number[]>()

  const scale = () => Math.max(1, Math.floor((settings?.rows ?? glyphRows) / glyphRows))
  const columnsOf = (text: string) => {
    const key = `${String(scale())}:${text}`
    let columns = columnsCache.get(key)
    if (!columns) {
      columns = textColumns(text, scale())
      columnsCache.set(key, columns)
    }
    return columns
  }
  const scrolls = () => settings?.mode === "scroll" && !reduced
  const pages = () => {
    const text = settings?.messages[message] ?? ""
    return settings ? pagesOf(text, settings.columns, scale()) : [text]
  }

  function frameNow(): Frame {
    if (!settings) return { columns: [], offset: 0 }
    if (scrolls()) return { columns: columnsOf(settings.messages[message] ?? ""), offset }
    const columns = columnsOf(pages()[page] ?? "")
    return { columns, offset: -Math.floor((settings.columns - columns.length) / 2) }
  }

  function paint() {
    if (!settings || !geometry || !unlit || !sprite) return
    const paintStarted = performance.now()
    const context = canvas.getContext("2d", planCanvas().settings)
    if (!context) return
    shown = frameNow()
    context.globalCompositeOperation = "copy"
    context.drawImage(unlit, 0, 0)
    context.globalCompositeOperation = "lighter"
    const { pitch, left, top } = geometry
    const half = sprite.width / 2
    const firstRow = Math.floor((settings.rows - glyphRows * scale()) / 2)
    for (let column = 0; column < settings.columns; column++) {
      const dots = shown.columns[shown.offset + column] ?? 0
      if (!dots) continue
      const x = left + (column + 0.5) * pitch - half
      for (let row = 0; row < settings.rows; row++) {
        if (dots & (1 << (row - firstRow))) context.drawImage(sprite, x, top + (row + 0.5) * pitch - half)
      }
    }
    handlers.onPaint?.(performance.now() - paintStarted)
  }

  function layout() {
    if (!settings || size.width < 2 || size.height < 2) return
    geometry = geometryOf(size.width, size.height, settings)
    const width = Math.round(size.width * geometry.ratio)
    const height = Math.round(size.height * geometry.ratio)
    sized(canvas, width, height)
    unlit ??= document.createElement("canvas")
    paintUnlit(unlit, width, height, geometry, settings)
    sprite = litSprite(geometry.pitch, ledPalettes[settings.color])
    paint()
  }

  const running = () =>
    Boolean(
      settings && !settings.paused && onScreen && settings.messages.length && document.visibilityState !== "hidden",
    )

  function stop() {
    cancelAnimationFrame(frame)
    clearTimeout(timer)
    frame = 0
    timer = undefined
  }

  function showMessage(index: number) {
    const count = settings?.messages.length ?? 0
    message = count ? index % count : 0
    page = 0
    offset = -(settings?.columns ?? 0)
    handlers.onMessage(message)
  }

  function step(now: number) {
    if (!settings) return
    const length = columnsOf(settings.messages[message] ?? "").length
    const next = startOffset + Math.floor(((now - started) * settings.speed) / 1000)
    if (next >= length) {
      showMessage(message + 1)
      started = now
      startOffset = offset
    } else {
      offset = next
    }
    if (shown.offset !== offset || shown.columns !== columnsOf(settings.messages[message] ?? "")) paint()
    frame = requestAnimationFrame(step)
  }

  function hold() {
    timer = setTimeout(() => {
      if (page + 1 < pages().length) page += 1
      else showMessage(message + 1)
      paint()
      hold()
    }, settings?.holdMs ?? 3000)
  }

  function run() {
    stop()
    if (!running()) return
    if (scrolls()) {
      started = performance.now()
      startOffset = offset
      frame = requestAnimationFrame(step)
    } else {
      hold()
    }
  }

  const resize = new ResizeObserver(([entry]) => {
    if (!entry) return
    size = { width: entry.contentRect.width, height: entry.contentRect.height }
    layout()
  })
  resize.observe(board)

  const visibility =
    typeof IntersectionObserver === "function"
      ? new IntersectionObserver(([entry]) => {
          onScreen = entry?.isIntersecting ?? true
          run()
        })
      : undefined
  visibility?.observe(board)

  const motion = typeof matchMedia === "function" ? matchMedia("(prefers-reduced-motion: reduce)") : undefined
  const onMotion = () => {
    reduced = prefersReducedMotion()
    page = 0
    offset = -(settings?.columns ?? 0)
    paint()
    run()
  }
  motion?.addEventListener("change", onMotion)
  document.addEventListener("visibilitychange", run)

  return {
    set(next: LedMatrixSettings) {
      const previous = settings
      settings = next
      const messagesChanged =
        !previous ||
        previous.messages.length !== next.messages.length ||
        previous.messages.some((text, index) => text !== next.messages[index])
      const shapeChanged =
        !previous || previous.columns !== next.columns || previous.rows !== next.rows || previous.color !== next.color
      if (messagesChanged) showMessage(0)
      else if (previous.mode !== next.mode) {
        page = 0
        offset = -next.columns
      }
      if (shapeChanged) {
        columnsCache.clear()
        layout()
      } else if (messagesChanged || previous.mode !== next.mode) paint()
      const pacingChanged =
        !previous ||
        messagesChanged ||
        previous.mode !== next.mode ||
        previous.paused !== next.paused ||
        previous.speed !== next.speed ||
        previous.holdMs !== next.holdMs
      if (pacingChanged) run()
    },
    destroy() {
      stop()
      resize.disconnect()
      visibility?.disconnect()
      motion?.removeEventListener("change", onMotion)
      document.removeEventListener("visibilitychange", run)
    },
  }
}

export { createLedMatrixEngine, ledPalettes }
export type { LedColor, LedMatrixHandlers, LedMatrixMode, LedMatrixSettings }

import { ledMatrixGlyphData } from "@/components/ui/led-matrix-glyphs"

/** How tall a glyph is, in dots; every glyph is five dots wide at most. */
const glyphRows = 7
const glyphColumns = 5
const spaceColumns = 3

type Glyph = { columns: number[] }

const glyphStride = 1 + glyphRows

function columnsOfRows(rows: number[], tabular: boolean): number[] {
  const columns = Array.from({ length: glyphColumns }, (_, column) =>
    rows.reduce((mask, row, index) => (row & (1 << (glyphColumns - 1 - column)) ? mask | (1 << index) : mask), 0),
  )
  if (tabular) return columns
  const first = columns.findIndex((mask) => mask !== 0)
  if (first === -1) return Array.from({ length: spaceColumns }, () => 0)
  const last = columns.findLastIndex((mask) => mask !== 0)
  return columns.slice(first, last + 1)
}

function parseGlyphs(): Map<string, Glyph> {
  const glyphs = new Map<string, Glyph>()
  for (let index = 0; index < ledMatrixGlyphData.length; index += glyphStride) {
    const char = ledMatrixGlyphData[index]!
    const rows = Array.from(ledMatrixGlyphData.slice(index + 1, index + glyphStride), (digit) =>
      Number.parseInt(digit, 32),
    )
    glyphs.set(char, { columns: columnsOfRows(rows, /\d/.test(char)) })
  }
  return glyphs
}

let glyphTable: Map<string, Glyph> | undefined
const glyphsOnce = () => (glyphTable ??= parseGlyphs())

/** The glyph a character shows: its own, its letter without the accent, or `?` for anything the font lacks. */
function glyphOf(char: string): Glyph {
  const glyphs = glyphsOnce()
  return (
    glyphs.get(char) ??
    glyphs.get(char.normalize("NFD").replaceAll(/\p{Mark}/gu, "")) ??
    glyphs.get(char.normalize("NFKD")[0] ?? "") ??
    glyphs.get("?")!
  )
}

/** Whether the font draws this character itself, rather than a stand-in. */
function hasGlyph(char: string) {
  return glyphsOnce().has(char)
}

/**
 * A line of text as columns of dots, one gap between characters: each number is a column, bit 0 its top dot. `scale`
 * repeats every dot that many times across and down, for a sign with more rows than a glyph.
 */
function textColumns(text: string, scale = 1): number[] {
  const columns: number[] = []
  const chars = [...text.normalize("NFC")]
  for (const [index, char] of chars.entries()) {
    for (const column of glyphOf(char).columns) {
      const scaled = scale === 1 ? column : scaleColumn(column, scale)
      for (let repeat = 0; repeat < scale; repeat++) columns.push(scaled)
    }
    if (index < chars.length - 1) for (let repeat = 0; repeat < scale; repeat++) columns.push(0)
  }
  return columns
}

function scaleColumn(column: number, scale: number) {
  let scaled = 0
  for (let row = 0; row < glyphRows; row++) {
    if (!(column & (1 << row))) continue
    for (let repeat = 0; repeat < scale; repeat++) scaled |= 1 << (row * scale + repeat)
  }
  return scaled
}

const measure = (text: string, scale: number) => textColumns(text, scale).length

/**
 * Splits a message into pages that each fit `columns` dots across: whole words where they fit, a word longer than the
 * sign broken between characters.
 */
function pagesOf(text: string, columns: number, scale = 1): string[] {
  const pages: string[] = []
  let line = ""
  const push = () => {
    if (line) pages.push(line)
    line = ""
  }
  for (const word of text.split(/\s+/).filter(Boolean)) {
    const candidate = line ? `${line} ${word}` : word
    if (measure(candidate, scale) <= columns) {
      line = candidate
      continue
    }
    push()
    if (measure(word, scale) <= columns) {
      line = word
      continue
    }
    for (const char of word) {
      if (line && measure(line + char, scale) > columns) push()
      line += char
    }
  }
  push()
  return pages.length ? pages : [""]
}

export { glyphColumns, glyphOf, glyphRows, hasGlyph, pagesOf, textColumns }

import { useEffect, useEffectEvent, useLayoutEffect, useRef, useState, type RefObject } from "react"

import { createLedMatrixEngine, type LedMatrixSettings } from "@/components/ui/led-matrix-engine"

type LedMatrixElements = {
  board: RefObject<HTMLElement | null>
  canvas: RefObject<HTMLCanvasElement | null>
}

type Engine = ReturnType<typeof createLedMatrixEngine>

/**
 * Runs the sign's engine on the canvas while it's mounted and returns the index of the message on it. It paints only
 * when a dot changes, and stops while the sign is paused, off screen or in a hidden tab.
 */
function useLedMatrixScene(
  elements: LedMatrixElements,
  settings: LedMatrixSettings,
  onPaint?: (milliseconds: number) => void,
) {
  const [message, setMessage] = useState(0)
  const engine = useRef<Engine | null>(null)
  const latest = useEffectEvent(() => settings)
  const painted = useEffectEvent((milliseconds: number) => onPaint?.(milliseconds))

  useEffect(() => {
    const board = elements.board.current
    const canvas = elements.canvas.current
    if (!board || !canvas) return
    const created = createLedMatrixEngine(canvas, board, { onMessage: setMessage, onPaint: painted })
    created.set(latest())
    engine.current = created
    return () => {
      created.destroy()
      engine.current = null
    }
  }, [elements])

  const { messages, columns, rows, mode, speed, holdMs, color, paused } = settings
  useLayoutEffect(() => {
    engine.current?.set({ messages, columns, rows, mode, speed, holdMs, color, paused })
